import{_ as o,o as e,c as t,a5 as i}from"./chunks/framework.CXvGqWf0.js";const f=JSON.parse('{"title":"漫画 · 第 56 话 包含块与格式化上下文","description":"","frontmatter":{},"headers":[],"relativePath":"comics/mechanism/EP.56-containing-block.md","filePath":"comics/mechanism/EP.56-containing-block.md","lastUpdated":1793853676000}'),n={name:"comics/mechanism/EP.56-containing-block.md"};function r(l,a,c,d,s,h){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="漫画-·-第-56-话-包含块与格式化上下文" tabindex="-1">漫画 · 第 56 话 包含块与格式化上下文 <a class="header-anchor" href="#漫画-·-第-56-话-包含块与格式化上下文" aria-label="Permalink to &quot;漫画 · 第 56 话 包含块与格式化上下文&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/mechanism/02-containing-block-formatting-context">docs/mechanism/02-containing-block-formatting-context.md</a> ｜ 原画：<a href="./EP.56-containing-block.svg">EP.56-containing-block.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她给卡片加了个入场动画，绝对定位的角标立刻跑到了屏幕角落。</li><li><strong>标签君</strong>：结构师。负责画出包含块链与格式化上下文，解释“谁参照谁、谁隔离谁”。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱的角标本来贴卡片右上角，加了 <code>transform</code> 动画后跑到外层容器边缘。她以为是 z-index 的锅，标签君摇头：transform 创建了包含块，绝对定位的参照系换了人。另一边，父子 margin 折叠让面板顶部凭空多出一截，<code>overflow:hidden</code> 又裁掉了阴影。两个 bug，一个根因：没弄清包含块与格式化上下文。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>角标 <code>position:absolute; top:8px; right:8px</code>，卡片没有定位祖先时，它参照更外层的定位容器；给卡片加 <code>transform: translateZ(0)</code> 后，卡片成为包含块，角标突然贴到卡片内边距盒。像素酱的动画只是“加了个变换”，布局契约却被悄悄改写。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>包含块决定百分比尺寸与 inset 的参照矩形：static/relative 参照最近块容器，absolute 参照最近已定位祖先，fixed 参照视口；<code>transform/filter/contain:paint</code> 即使 static 也会创建包含块。格式化上下文决定排布与隔离：BFC 能包含浮动、阻断 margin 折叠；Flex/Grid 各自建立 FFC/GFC。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>修复手法各有对应：角标问题给卡片显式 <code>position:relative</code> 或把浮层 Portal 到 body；margin 穿透用 <code>display:flow-root</code> 而不是 <code>overflow:hidden</code>；浮动塌陷同样用 flow-root。像素酱把“加动画”改成“先声明定位契约”，角标归位，阴影也不再被裁。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>transform</code>、<code>filter</code>、<code>contain:paint</code> 会创建包含块，动画属性会改写定位参照。</li><li><code>display:flow-root</code> 是建立 BFC 的首选，副作用比 <code>overflow:hidden</code> 小。</li><li>Flex/Grid 子项没有普通流的 margin 折叠，别混用 BFC 解释。</li><li>绝对定位元素必须有显式定位祖先，别依赖“碰巧”。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：父级加了 <code>overflow:hidden</code> 后 margin 折叠消失了，但下拉菜单也被裁掉了，怎么改？</p><p><strong>答</strong>：把父级的 <code>overflow:hidden</code> 换成 <code>display:flow-root</code>。两者都能建立 BFC 阻断 margin 折叠，但 flow-root 不裁剪溢出内容，适合包含下拉、阴影、焦点环的容器。若确实需要裁剪，应把浮层移到 body 或使用 popover 顶层。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>切换定位祖先 / transform / contain，观察角标参照系：<a href="./../../examples/mechanism/02-containing-block-formatting-context">examples/mechanism/02-containing-block-formatting-context</a></li><li>对比普通块与 flow-root 的 margin 折叠、浮动包裹效果。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>位置对了，为什么一读尺寸就卡？第 57 话《布局计算与强制同步布局》——layout thrashing 的读写交错现场。</p>',22)])])}const p=o(n,[["render",r]]);export{f as __pageData,p as default};
